package com.theone.series;
import android.content.*;import android.widget.GridView;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicInteger;
@RunWith(AndroidJUnit4.class) public class StarterStartupTest {
 @Test public void freshInstallShowsBundledTitlesWithoutEitherProvider()throws Exception{Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();Intent intent=new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK).putExtra("starter_test_mode",true);long start=android.os.SystemClock.elapsedRealtime();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(intent)){AtomicInteger count=new AtomicInteger();while(count.get()==0&&android.os.SystemClock.elapsedRealtime()-start<4000){scenario.onActivity(a->count.set(((GridView)a.findViewById(1020)).getCount()));Thread.sleep(50);}assertTrue("Starter titles are visible without any network response",count.get()>0);assertTrue("Fresh startup finishes within four seconds on phone emulator",android.os.SystemClock.elapsedRealtime()-start<4000);}}
}
